#!/usr/bin/env python3\n"""Offline structural QA for POTOK CRM Core. Does not connect to or modify a server."""\nfrom pathlib import Path\nimport ast, hashlib, json, re, sys, zipfile\n\nROOT = Path(__file__).resolve().parents[1]\nerrors, warnings = [], []\n\ndef check(condition, message):\n    (warnings if condition is None else errors if not condition else []).append(message)\n\n# Python syntax\npy_files = list(ROOT.rglob("*.py"))\nfor path in py_files:\n    try:\n        ast.parse(path.read_text(encoding="utf-8"), filename=str(path))\n    except SyntaxError as exc:\n        errors.append(f"Python syntax: {path.relative_to(ROOT)}:{exc.lineno}: {exc.msg}")\n\n# Required security controls / structure\nrequired = [\n    "app/dependencies.py", "app/permissions.py", "app/security.py", "app/rbac.py", "app/audit.py",\n    "app/routers/auth.py", "app/routers/admin.py", "app/tenant_context.py",\n    "migrations/versions/0001_initial_core.py",\n    "migrations/versions/0002_membership_role.py", "migrations/versions/0003_tenant_rls.py", "migrations/versions/0004_rbac_audit.py",\n]\nfor item in required:\n    if not (ROOT/item).is_file():\n        errors.append(f"Missing required file: {item}")\n\nconfig = (ROOT/"app/config.py").read_text(encoding="utf-8")\nauth = (ROOT/"app/routers/auth.py").read_text(encoding="utf-8")\nmodels = (ROOT/"app/models.py").read_text(encoding="utf-8")\ndeps = (ROOT/"app/dependencies.py").read_text(encoding="utf-8")\nperm = (ROOT/"app/permissions.py").read_text(encoding="utf-8")\nchecks = {\n    "Bootstrap registration defaults off": "allow_bootstrap_registration: bool = False" in config,\n    "Registration endpoint checks bootstrap flag": "if not settings.allow_bootstrap_registration" in auth,\n    "Membership role exists in ORM": 'role: Mapped[str]' in models,\n    "Authenticated requests re-check membership in DB": "Membership.user_id == user_id" in deps and "Membership.company_id == company_id" in deps,\n    "RBAC rejects unauthorized roles": "status_code=403" in perm,\n    "Admin endpoint uses director guard": "Depends(require_director)" in (ROOT/"app/routers/admin.py").read_text(encoding="utf-8"),\n}\nfor label, passed in checks.items():\n    if not passed: errors.append("Security check failed: "+label)\n\n# No embedded likely secrets (ignore .env.example placeholders)\nsecret_patterns = [r"(?i)(api[_-]?key|secret|password)\\s*[:=]\\s*[\"'][A-Za-z0-9/_+=.-]{20,}"]\nfor path in ROOT.rglob("*"):\n    if path.is_file() and path.suffix in {".py",".ts",".tsx",".js",".json",".yml",".yaml"}:\n        text = path.read_text(encoding="utf-8", errors="ignore")\n        if any(re.search(pat, text) for pat in secret_patterns):\n            errors.append(f"Possible hard-coded secret: {path.relative_to(ROOT)}")\n\n# package JSON syntax\nfor path in ROOT.rglob("package.json"):\n    try: json.loads(path.read_text(encoding="utf-8"))\n    except Exception as exc: errors.append(f"Invalid JSON {path.relative_to(ROOT)}: {exc}")\n\nprint(f"Python files syntax-checked: {len(py_files)}")\nprint(f"Security/structure checks: {len(checks)}")\nfor label, passed in checks.items(): print(f"[{'OK' if passed else 'FAIL'}] {label}")\nif warnings:\n    for item in warnings: print("[WARN]", item)\nif errors:\n    for item in errors: print("[FAIL]", item)\n    sys.exit(1)\nprint("RESULT: PASS (static checks only; no database/integration/runtime tests performed)")\n